    return {'remote_commit':commit,'run':decode(_api(f'repos/{REPOSITORY}/actions/runs/{run_id}')),'jobs':decode(_api(f'repos/{REPOSITORY}/actions/runs/{run_id}/jobs?per_page=100'))}
